renderKyc=function(d){const labels={VERIFIED:'Documents checked',ACTION_REQUIRED:'A few details need attention',REJECTED:'We could not verify these details'};let h='<div class="card"><h3>'+esc(labels[d.verdict]||d.verdict)+'</h3><p class="small-text">Document checks use local reference records. Live GST / Udyam verification is not connected.</p>';const findings=(d.findings||[]).filter(f=>f.sev!=='info');h+=findings.length?'<ul class="findings">'+findings.map(f=>'<li>'+esc(f.msg.replace(/\s*\(sharpness [^)]+\)/g,''))+(f.fix?'<br><small>'+esc(f.fix)+'</small>':'')+'</li>').join('')+'</ul>':'<p>No document issues found.</p>';h+='</div>';$('kres').innerHTML=h;if(S.order&&$('kycOrder').value===S.order.id)loadOrder(S.order.id)};
renderOrder=function(o){
 if(!o.activation){priorOrder(o);return}
 const a=o.activation,by=Object.fromEntries(a.tasks.map(t=>[t.id,t])),verification=by.verification,canRecover=!staffView&&o.status!=='cancelled'&&a.alternatives.length;
 let h='<div class="card"><div class="row"><h3>'+esc(o.business_name)+'</h3><span class="pill">'+esc(labelStatus(o.status))+'</span></div><p class="small-text">Reference: '+esc(o.id)+'</p><div class="task-summary"><div><strong>'+a.completed_services+'/'+a.total_services+'</strong> service checklists complete</div><div>Estimated completion: <b>'+esc(a.forecast?dateLabel(a.forecast):'Awaiting an updated plan')+'</b><br><small>Dates are estimates. Your installation appointment is not yet confirmed.</small></div><div>'+money(o.monthly)+'/mo + '+money(o.setup)+' setup</div></div>';
 h+='<p class="small-text">Live telecom activation is not connected. Checklist progress does not confirm that a service is live.</p>';
 if(o.status==='cancelled')h+='<div class="note">This order is cancelled. No further activation actions are available.</div>';
 else if(verification?.status!=='complete')h+='<div class="note">Next step: verify the business documents. '+(!staffView||canReviewKyc()?'<button class="sec" id="trackToKyc">Continue verification</button>':'')+'</div>';
 if(!staffView)h+='<details><summary>Private order access</summary><p class="small-text">Signed-in customers can reopen this order with their verified phone. Local demo orders may also have a private access code.</p><input readonly type="password" aria-label="Private order access code" id="savedAccess" value="'+esc(sessionStorage.getItem('uo_token_'+o.id)||'')+'"><button class="ghost" id="showAccess">Show / hide</button></details>';
 if(staffView)h+='<p class="small-text">Partner: '+esc(o.partner_code||'Direct')+' · KYC: '+esc(o.kyc_status)+'</p>';
 if(canActivate()){h+='<details class="operator-panel" open><summary>Activation evidence controls</summary><p class="small-text">'+esc(a.provisioning)+'. Live telecom provisioning is not connected.</p>';
 if(testToolsEnabled()&&verification?.status!=='complete'&&o.status!=='cancelled')h+='<p><button class="ghost" id="demoVerify">Simulate verification</button> <small>No documents are checked by this action.</small></p>';
 h+='<label class="fld">Evidence for the next event<input id="taskEvidence" placeholder="Describe the check, result and reference" maxlength="500"></label><label class="fld">Delay in days<input id="taskDelay" type="number" min="1" max="365" value="7" style="max-width:110px"></label><div id="taskError" role="status"></div></details>';
 }
 h+='<div class="service-progress">'+o.items.map(i=>{
 const tasks=a.tasks.filter(t=>t.site_id===i.site_id&&t.product_id===i.id);if(!tasks.length)return '';
 const check=tasks.find(t=>t.kind==='check'),problem=tasks.find(t=>t.status==='failed'||t.status==='delayed');const status=check?.status==='complete'?'Checks complete':problem?labelStatus(problem.status):verification?.status!=='complete'?'Awaiting verification':'In progress';
 return '<details class="service-status" '+(problem?'open':'')+'><summary><span>'+esc(i.name)+'<small>'+esc(siteLabel(i.site_id,o.plan?.context))+'</small></span><span class="pill">'+esc(status)+'</span></summary>'+tasks.map(t=>'<div class="task-card '+esc(t.status)+'"><b>'+esc(serviceLabel(t))+'</b><p class="small-text">'+esc(labelStatus(t.status))+' · '+esc(t.forecast?'Estimate: '+dateLabel(t.forecast):'Date will be updated')+'</p>'+(t.blocked_by.length?'<p class="small-text">Waiting for '+t.blocked_by.map(id=>esc(by[id]?.kind==='verification'?'business verification':by[id]?.label?.replace(': useful-service check',': final check')||'the previous step')).join(', ')+'.</p>':'')+(canActivate()?'<p class="small-text">'+esc(t.id)+(t.evidence?' · '+esc(t.evidence)+' · '+esc(t.source):'')+'</p>':'')+(canActivate()&&t.status!=='complete'&&o.status!=='cancelled'?'<div class="row"><button class="sec" data-task="'+esc(t.id)+'" data-action="complete" '+(!t.can_complete?'disabled':'')+'>Complete step</button><button class="ghost" data-task="'+esc(t.id)+'" data-action="delay" '+(t.status==='failed'?'disabled':'')+'>Record delay</button><button class="ghost" data-task="'+esc(t.id)+'" data-action="fail">Record failure</button>'+(['failed','delayed'].includes(t.status)?'<button class="sec" data-task="'+esc(t.id)+'" data-action="retry">Retry</button>':'')+'</div>':'')+'</div>').join('')+'</details>';
 }).join('')+'</div>';
 if(canRecover)h+='<div class="note"><b>A connection needs an alternative plan</b><p>Review another connection option and its charges. Your existing order will change only after you accept the revised plan.</p><button class="sec" id="reviewAlternative">Review connection options</button></div>';
 if(canActivate())h+='<details><summary>Recent activation evidence</summary>'+a.events.map(e=>'<p class="small-text">'+esc(e.recorded_at)+' · '+esc(e.task_id)+' · '+esc(e.action)+' · '+esc(e.source)+'</p>').join('')+'</details>';
 h+='</div>';$('trackRes').innerHTML=h;if($('showAccess'))$('showAccess').onclick=()=>$('savedAccess').type=$('savedAccess').type==='password'?'text':'password';if($('trackToKyc'))$('trackToKyc').onclick=()=>go('kyc');
 $('trackRes').querySelectorAll('[data-task]').forEach(b=>b.onclick=async()=>{const t=by[b.dataset.task],evidence=$('taskEvidence').value.trim();if(evidence.length<5){$('taskError').textContent='Enter evidence (at least 5 characters).';$('taskEvidence').focus();return}if(!$('taskDelay').reportValidity())return;b.disabled=true;try{const updated=await api('/api/orders/'+o.id+'/events',{event_id:newId(),task_id:t.id,action:b.dataset.action,expected_version:t.version,evidence,delay_days:Number($('taskDelay').value)},operatorHeaders());S.order=updated;renderOrder(updated)}catch(e){$('taskError').textContent=e.message;b.disabled=false}});
 if($('demoVerify'))$('demoVerify').onclick=async()=>{try{const updated=await api('/api/orders/'+o.id+'/demo-verification',{},operatorHeaders());S.order=updated;syncOrderFields(updated);renderOrder(updated)}catch(e){$('taskError').textContent=e.message}};
 if($('reviewAlternative'))$('reviewAlternative').onclick=()=>showRecovery(o);
 if($('paymentLink'))$('paymentLink').onclick=()=>paymentAction(o.id,true);if($('refreshPayment'))$('refreshPayment').onclick=()=>paymentAction(o.id,false);
};
