 $('staffLeadsPanel').insertAdjacentHTML('beforeend','<div class="card" id="routingCard"><h3>Assistance from actual order blockers</h3><p class="muted">Digital completions retain partner attribution. Routing and pilot assignment do not send messages or dispatch staff.</p><div id="routingOrders"></div></div><div class="card" id="simPolicyCard"><h3>Assistance policy experiment</h3><p class="muted">Explore when a lower-propensity lead is worth helping. All effects below are editable assumptions.</p><div class="sim-controls"><label class="fld">Assistance budget (₹)<input id="simBudget" type="number" min="0" value="5000"></label><label class="fld">Staff capacity<input id="simCapacity" type="number" min="0" value="20"></label><label class="fld">Cost per contact (₹)<input id="simCost" type="number" min="1" value="250"></label><label class="fld">Assumed lift (percentage points)<input id="simEffect" type="number" min="-100" max="100" value="12"></label><label class="fld">Contribution margin (%)<input id="simMargin" type="number" min="0" max="100" value="30"></label><label class="fld">12-month retention assumption (%)<input id="simRetention" type="number" min="0" max="100" value="75"></label><label class="fld">Available skill<select id="simSkill"><option value="all">All skills</option><option>verification</option><option>installation</option><option>commercial</option><option>billing</option><option>advisor</option></select></label></div><button class="pri" id="simulatePolicy">Compare policies</button><div id="simResult"></div></div>');
 $('staffSystemPanel').insertAdjacentHTML('beforeend','<div class="card test-only"><h3>WhatsApp conversation preview</h3><p class="muted">Local English pilot. No messages are sent. Type START to try the same advisor used by the signed WhatsApp webhook.</p><div class="bot-log" id="botLog"></div><div class="row"><input id="botInput" placeholder="START" class="grow"><button class="sec" id="botSend">Preview reply</button></div></div>');
