 for(const [id,min,max] of [['bizname',2,160],['contact',2,120],['address',5,400]]){$(id).required=true;$(id).minLength=min;$(id).maxLength=max}
 $('phone').required=true;$('phone').pattern='\\+?[0-9 ()-]{10,32}';$('phone').maxLength=32;$('phone').title='Enter 10 to 15 digits, optionally with a country code.';$('email').maxLength=254;
 for(const [id,auto] of [['bizname','organization'],['contact','name'],['phone','tel'],['email','email'],['address','street-address']])$(id).autocomplete=auto;
 document.querySelectorAll('label.fld').forEach(label=>{const next=label.nextElementSibling;if(next?.matches('input,textarea,select')&&next.id)label.htmlFor=next.id});
 for(const id of ['orderMsg','kres','trackRes','boMeta']){$(id).setAttribute('role','status');$(id).setAttribute('aria-live','polite')}
 $('free').setAttribute('aria-label','Describe your business');$('mic').setAttribute('aria-label','Voice input');$('botInput').setAttribute('aria-label','Message for the WhatsApp preview');$('registryNumber').setAttribute('aria-label','Registration number');$('adminToken').setAttribute('aria-label','Staff access token');
 const oldGo=go;go=function(tab){if(tab==='bo'&&!staffView)return;const button=document.querySelector('nav button[data-t="'+tab+'"]');if(!staffView&&button?.disabled)return;stopSpeech();stopListening();oldGo(tab);$('welcomeZone').hidden=true;document.querySelectorAll('nav button').forEach(b=>b.setAttribute('aria-current',b.dataset.t===tab?'page':'false'));updateJourneyNav();window.scrollTo({top:0,behavior:'smooth'})};
