loadPartner=async function(){let code=(staffIdentity.partner_code||$('partnerCode').value).trim().toUpperCase();if(!code)return;$('partnerSummary').textContent='Preparing signed referral…';try{const referral=await api('/api/partner/referral?code='+encodeURIComponent(code),undefined,operatorHeaders());code=referral.code;S.partner=code;const url=new URL(referral.url);S.partnerExp=Number(url.searchParams.get('partner_exp'));S.partnerSig=url.searchParams.get('partner_sig')||'';localStorage.setItem('udyam_partner',code);localStorage.setItem('udyam_partner_referral',JSON.stringify({code,expires:S.partnerExp,signature:S.partnerSig}));applyLang();$('partnerQr').src=referral.qr_data_url;$('partnerQr').classList.remove('hide');const d=await api('/api/partner/summary?code='+encodeURIComponent(code),undefined,operatorHeaders());$('partnerSummary').innerHTML='<b>'+esc(code)+'</b><p>Referral valid until '+esc(dateLabel(referral.expires_at))+'</p><p>'+d.orders+' attributed orders · '+money(d.monthly_value)+'/month</p><p>Estimated first-month commission '+money(d.month1_commission)+' · annual trail '+money(d.annual_trail)+'</p>'}catch(e){$('partnerSummary').textContent=e.message}};
$('partnerBtn').onclick=loadPartner;
